// Look for project stat cards and check their CSS for animations/transitions/delays
const allElements = document.querySelectorAll('*');
const results = [];
for (const el of allElements) {
  const style = getComputedStyle(el);
  if (style.animationDelay && style.animationDelay !== '0s') {
    results.push({
      tag: el.tagName,
      class: el.className,
      text: el.textContent.substring(0, 50),
      animationDelay: style.animationDelay,
      animationName: style.animationName,
      animationDuration: style.animationDuration,
      transitionDelay: style.transitionDelay
    });
  }
  if (style.transitionDelay && style.transitionDelay !== '0s') {
    results.push({
      tag: el.tagName,
      class: el.className,
      text: el.textContent.substring(0, 50),
      transitionDelay: style.transitionDelay,
      transitionDuration: style.transitionDuration,
      transitionProperty: style.transitionProperty
    });
  }
}
return JSON.stringify(results.slice(0, 30));

// Check for any setTimeout or setInterval calls by looking at the source code
// First, let's look at all script tags
const scripts = document.querySelectorAll('script');
const results = [];
for (const s of scripts) {
  results.push({src: s.src, type: s.type, textLength: s.textContent.length, text: s.textContent.substring(0, 200)});
}
return JSON.stringify(results);

// Fetch the ProjectCard source to see how stats are fetched
const resp = await fetch('/src/components/ProjectCard.tsx');
const text = await resp.text();
return text;

